20		import { onMount } from 'svelte';
21		import { DEFAULT_CATEGORY_COLOR, type Category } from '$lib/types/Category';
22		import type { CategoryGroup } from '$lib/types/Hierarchy';
23		import { supabase } from '$lib/supabaseClient';
24		import { ExpenseService } from '$lib/services/ExpenseService';
25	
26		// Component props
27		interface Props {
28			currentCategory?: Category | null;
29			categories?: Category[];
30			/** Spending-hierarchy Groupings; when supplied, inline creation offers a
31			 * "Group" selector so a new category can be filed straight away. */
