34			familyId?: string;
35			merchantName?: string;
36			onCategorySelected?: (category: Category) => void;
37			onCreateNewCategory?: (data: {
38				name: string;
39				color: string | null;
40				groupId: string | null;
41			}) => void;
42			onVendorRuleCreated?: (data: { merchantName: string; categoryId: string }) => void;
43		}
44	
45		let {
46			currentCategory = null,
47			categories = [],
48			groups = [],
49			onCategorySelect = () => {},
50			familyId = '',
51			merchantName = '',
52			onCategorySelected,
53			onCreateNewCategory,
54			onVendorRuleCreated
55		}: Props = $props();
56	
57		// Groupings offered in the inline-creation "Group" selector, alphabetical.
58		const sortedGroups = $derived(groups.slice().sort((a, b) => a.name.localeCompare(b.name)));
59	
60		// Component state
61		let isOpen = $state(false);
62		let searchQuery = $state('');
63		let selectedIndex = $state(0);
64		let dropdownElement: HTMLDivElement;
65		let searchInputElement = $state<HTMLInputElement>();
66	
67		// #{#exp3b} Inline creation state
68		let isInCreationMode = $state(false);
69		let newCategoryName = $state('');
70		let newCategoryColor = $state('');
71		let newCategoryGroupId = $state('');
72		let creationError: string | null = $state(null);
73		let nameInputElement = $state<HTMLInputElement>();
74	
75		// Vendor rule state
76		let vendorRule: { category_id: string; category_name: string } | null = $state(null);
77		let loadingVendorRule = $state(false);
78	
79		// Computed: Filter categories based on search query
80		let filteredCategories = $derived(filterCategories(categories, searchQuery));
81	
82		/**
83		 * Filter categories by search query (case-insensitive partial match)
84		 * #{#exp2a} Criterion 4
85		 */
86		function filterCategories(cats: Category[], query: string): Category[] {
87			if (!query || query.trim() === '') {
88				return cats;
89			}
90			const normalizedQuery = query.toLowerCase();
91			return cats.filter((cat) => cat.name.toLowerCase().includes(normalizedQuery));
92		}
93	
94		/**
95		 * Open dropdown and focus search input
96		 * #{#exp2a} Criterion 2, 3
97		 */
98		async function openDropdown() {
99			isOpen = true;
100			searchQuery = '';
101			selectedIndex = 0;
102	
103			// Load vendor rule if merchant info is available
104			if (merchantName && familyId) {
105				loadingVendorRule = true;
106				try {
107					const expenseService = new ExpenseService(supabase);
108					vendorRule = await expenseService.getVendorRule(familyId, merchantName);
109				} catch (err) {
110					console.error('Error loading vendor rule:', err);
111					vendorRule = null;
112				} finally {
113					loadingVendorRule = false;
114				}
115			}
116	
117			// Auto-focus search input when dropdown opens
118			setTimeout(() => {
119				searchInputElement?.focus();
120			}, 0);
121		}
122	
123		/**
124		 * Close dropdown and reset state
125		 * #{#exp2a} Criterion 9
126		 */
127		function closeDropdown() {
128			isOpen = false;
129			searchQuery = '';
130			selectedIndex = 0;
131		}
132	
133		/**
134		 * Toggle dropdown open/close
135		 * #{#exp2a} Criterion 2
136		 */
137		function toggleDropdown() {
138			if (isOpen) {
139				closeDropdown();
140			} else {
141				openDropdown();
142			}
143		}
144	
145		/**
146		 * Handle category selection
147		 * #{#exp2a} Criterion 7
148		 */
149		function selectCategory(category: Category) {
150			if (!category) return;
151	
152			onCategorySelect(category);
153			onCategorySelected?.(category);
154			closeDropdown();
155		}
156	
157		/**
158		 * Handle keyboard navigation
159		 * #{#exp2a} Criterion 8
160		 */
161		function handleKeyDown(event: KeyboardEvent) {
162			const maxIndex = filteredCategories.length - 1;
163	
164			switch (event.key) {
165				case 'ArrowDown':
166					event.preventDefault();
167					selectedIndex = selectedIndex < maxIndex ? selectedIndex + 1 : selectedIndex;
168					break;
169	
170				case 'ArrowUp':
171					event.preventDefault();
172					selectedIndex = selectedIndex > 0 ? selectedIndex - 1 : selectedIndex;
173					break;
174	
175				case 'Enter':
176					event.preventDefault();
177					if (filteredCategories.length > 0 && selectedIndex >= 0) {
178						selectCategory(filteredCategories[selectedIndex]);
179					}
180					break;
181	
182				case 'Escape':
183					event.preventDefault();
184					closeDropdown();
185					break;
186			}
187		}
188	
189		/**
190		 * Handle click outside to close dropdown
191		 * #{#exp2a} Criterion 9
192		 */
193		function handleClickOutside(event: MouseEvent) {
194			const target = event.target as Node | null;
195			// Svelte 5 flushes state synchronously after a delegated click handler, so a
196			// click that toggles the dropdown's own content (e.g. "Create new category…")
197			// detaches its target from the DOM before this document-level listener runs.
198			// A detached target is never a genuine outside click — bail so we don't close.
199			if (target && !target.isConnected) return;
200			if (dropdownElement && !dropdownElement.contains(target)) {
201				closeDropdown();
202			}
203		}
204	
205		/**
206		 * Setup click outside listener
207		 */
208		onMount(() => {
209			document.addEventListener('click', handleClickOutside);
210			return () => {
211				document.removeEventListener('click', handleClickOutside);
212			};
213		});
214	
215		/**
216		 * Handle create new category click
217		 * #{#exp3b} Criterion 2 - Show inline input field
218		 */
