229			}, 0);
230		}
231	
232		/**
233		 * Cancel inline creation mode
234		 * #{#exp3b} Criterion 3
235		 */
236		function cancelInlineCreation() {
237			isInCreationMode = false;
238			newCategoryName = '';
239			newCategoryColor = '';
240			newCategoryGroupId = '';
241			creationError = null;
242		}
243	
244		/**
245		 * Validate new category name
246		 * #{#exp3b} Criteria 8, 9, 10
247		 */
248		function validateNewCategory(name: string): { isValid: boolean; error: string | null } {
249			const trimmedName = name.trim();
250	
251			// Criterion 9: Empty name validation
252			if (trimmedName.length === 0) {
253				return { isValid: false, error: 'Category name required' };
254			}
255	
256			// Criterion 10: Max length validation
257			if (trimmedName.length > 100) {
258				return { isValid: false, error: 'Category name must be 100 characters or less' };
259			}
260	
261			// Criterion 8: Duplicate validation (case-insensitive)
262			const isDuplicate = categories.some(
263				(cat) => cat.name.toLowerCase() === trimmedName.toLowerCase()
264			);
265			if (isDuplicate) {
266				return { isValid: false, error: 'Category already exists' };
267			}
268	
269			return { isValid: true, error: null };
270		}
271	
272		/**
273		 * Create new category
274		 * #{#exp3b} Criteria 5, 6, 7
275		 */
276		async function createNewCategory() {
277			// Validate input
278			const validation = validateNewCategory(newCategoryName);
279			if (!validation.isValid) {
280				creationError = validation.error;
281				return;
282			}
283	
284			// Dispatch event to parent with new category data
285			// Parent will handle CategoryService.createCategory() call
286			onCreateNewCategory?.({
287				name: newCategoryName.trim(),
288				color: newCategoryColor || null,
289				groupId: newCategoryGroupId || null
290			});
291	
292			// Reset state
293			cancelInlineCreation();
294		}
