296		/**
297		 * Handle keyboard navigation in creation form
298		 */
299		function handleCreationKeyDown(event: KeyboardEvent) {
300			if (event.key === 'Enter') {
301				event.preventDefault();
302				createNewCategory();
303			} else if (event.key === 'Escape') {
304				event.preventDefault();
305				cancelInlineCreation();
306			}
307		}
