 */
async bulkAssignCategory(
	receiptIds: string[],
	categoryId: string,
	source: 'manual' | 'auto' = 'manual'
): Promise<void> {
	if (!receiptIds || receiptIds.length === 0) {
		throw new Error('Receipt IDs are required');
	}

	if (!categoryId) {
		throw new Error('Category ID is required');
	}

	// Create batch update records
	const updates = receiptIds.map((receiptId) => ({
		receipt_id: receiptId,
		category_id: categoryId,
		categorization_source: source,
		updated_at: new Date().toISOString()
	}));

	// Batch upsert
	const { error } = await this.supabase.from('expense_categories').upsert(updates, {
		onConflict: 'receipt_id'
	});

	if (error) {
		throw new Error(error.message);
	}
}

