	 * @returns Number of expenses that were auto-assigned
	 *
	 * Specification: #{#vca5a} - Batch Auto-Categorization on Page Load (Family-scoped)
	 */
	async applyAllVendorRules(familyId: string, expenses: Expense[]): Promise<number> {
		// Return early if no expenses
		if (!expenses || expenses.length === 0) {
			return 0;
		}

		// Fetch all vendor rules for this family
		const { data: vendorRules, error } = await this.supabase
			.from('vendor_category_rules')
			.select('vendor_pattern, category_id')
			.eq('family_id', familyId);

		if (error) {
			throw new Error(error.message);
		}

		// Return early if no rules exist
		if (!vendorRules || vendorRules.length === 0) {
			return 0;
		}

		// Apply each rule and track total assignments
		let totalAssigned = 0;

		for (const rule of vendorRules) {
			const count = await this.applyRuleToVisibleExpenses(
				expenses,
				rule.vendor_pattern,
				rule.category_id
			);
			totalAssigned += count;
		}

		return totalAssigned;
	}
}

