362	
363			const { data, error } = await this.supabase
364				.from('vendor_category_rules')
365				.select('category_id, categories(name)')
366				.eq('family_id', familyId)
367				.eq('vendor_pattern', vendorPattern)
368				.single();
369	
370			if (error || !data) {
371				return null;
372			}
373	
374			const categories = coerceEmbed<{ name: string } | null>(data.categories);
