 *
 * Specification: #{#exp5a} - Vendor Rule Management (Family-scoped)
 */
async getVendorRule(
	familyId: string,
	merchantName: string
): Promise<{ category_id: string; category_name: string } | null> {
	if (!familyId || !merchantName) {
		return null;
	}

	const vendorPattern = this.normalizeVendor(merchantName);

	const { data, error } = await this.supabase
		.from('vendor_category_rules')
		.select('category_id, categories(name)')
		.eq('family_id', familyId)
		.eq('vendor_pattern', vendorPattern)
		.single();

	if (error || !data) {
		return null;
	}

	const categories = coerceEmbed<{ name: string } | null>(data.categories);

	return {
		category_id: data.category_id,
		category_name: categories?.name || 'Unknown'
	};
}

/**
 * Create vendor category rule
 *
 * @param familyId - Family ID
 * @param merchantName - Merchant name to match
 * @param categoryId - Category to assign
 *
 * Specification: #{#exp4a} - Automatic Category Assignment via Vendor Rules (Family-scoped)
 */
async createVendorRule(
	familyId: string,
	merchantName: string,
	categoryId: string
): Promise<void> {
	if (!familyId || !merchantName || !categoryId) {
		throw new Error('Family ID, merchant name, and category ID are required');
	}

	const vendorPattern = this.normalizeVendor(merchantName);

	const { error } = await this.supabase.from('vendor_category_rules').upsert(
		{
			family_id: familyId,
			vendor_pattern: vendorPattern,
			category_id: categoryId,
			updated_at: new Date().toISOString()
		},
		{
			onConflict: 'family_id,vendor_pattern'
		}
	);

	if (error) {
		throw new Error(error.message);
	}
}

