/**
 * Shared category-assignment behaviour, exercised through the port rather than a
 * page. Both list pages call `assignCategoryFromRow`, so these cases are the
 * single description of what picking a category in a row does.
 */

import { describe, it, expect, vi } from 'vitest';
import { assignCategoryFromRow, type CategoryAssignmentPort } from './categoryAssignment';
import type { VendorRuleCandidate } from '$lib/services/ExpenseService';
import type { Category } from '$lib/types/Category';

const GROCERIES: Category = {
	id: 'cat-groceries',
	family_id: 'fam-1',
	name: 'Groceries',
	color: '#00ff00'
} as Category;

function makePort(overrides: Partial<CategoryAssignmentPort> = {}): CategoryAssignmentPort {
	return {
		assignCategory: vi.fn().mockResolvedValue(undefined),
		bulkAssignCategory: vi.fn().mockResolvedValue(undefined),
		getVendorRule: vi.fn().mockResolvedValue(null),
		createVendorRule: vi.fn().mockResolvedValue(undefined),
		normalizeVendor: (name: string) => name.toLowerCase().trim(),
		applyRuleToVisibleExpenses: vi.fn().mockResolvedValue(0),
		...overrides
	};
}

const rows: VendorRuleCandidate[] = [
	{ receipt_id: 'r1', merchant_name: 'Safeway', category_id: null },
	{ receipt_id: 'r2', merchant_name: 'Safeway', category_id: null },
	{ receipt_id: 'r3', merchant_name: 'Dentist', category_id: 'cat-health' }
];

function callWith(port: CategoryAssignmentPort, selection: string[] = [], receiptId = 'r1') {
	return assignCategoryFromRow(port, {
		receiptId,
		category: GROCERIES,
		familyId: 'fam-1',
		selection: new Set(selection),
		visibleRows: rows
	});
}

describe('assignCategoryFromRow — single row', () => {
	it('assigns the category to just that receipt, manually', async () => {
		const port = makePort();
		await callWith(port);
		expect(port.assignCategory).toHaveBeenCalledWith('r1', 'cat-groceries', 'manual');
		expect(port.bulkAssignCategory).not.toHaveBeenCalled();
	});

	it('creates a vendor rule when the merchant has none', async () => {
		const port = makePort();
		const result = await callWith(port);
		expect(port.createVendorRule).toHaveBeenCalledWith('fam-1', 'Safeway', 'cat-groceries');
		expect(result).toMatchObject({ kind: 'single', ruleCreated: true });
	});

	it('leaves an existing vendor rule alone', async () => {
		const port = makePort({
			getVendorRule: vi.fn().mockResolvedValue({ category_id: 'cat-other', category_name: 'Other' })
		});
		const result = await callWith(port);
		expect(port.createVendorRule).not.toHaveBeenCalled();
		expect(port.applyRuleToVisibleExpenses).not.toHaveBeenCalled();
		expect(result).toMatchObject({ kind: 'single', ruleCreated: false, autoAppliedCount: 0 });
	});

	it('applies a newly created rule to the other visible rows and reports the count', async () => {
		const port = makePort({ applyRuleToVisibleExpenses: vi.fn().mockResolvedValue(2) });
		const result = await callWith(port);
		expect(port.applyRuleToVisibleExpenses).toHaveBeenCalledWith(rows, 'safeway', 'cat-groceries');
		expect(result).toMatchObject({ kind: 'single', autoAppliedCount: 2 });
	});

	it('skips vendor-rule work when there is no family', async () => {
		const port = makePort();
		const result = await assignCategoryFromRow(port, {
			receiptId: 'r1',
			category: GROCERIES,
			familyId: null,
			selection: new Set(),
			visibleRows: rows
		});
		expect(port.assignCategory).toHaveBeenCalledOnce();
		expect(port.getVendorRule).not.toHaveBeenCalled();
		expect(result).toMatchObject({ ruleCreated: false });
	});

	it('skips vendor-rule work for a row it cannot find a merchant for', async () => {
		const port = makePort();
		await callWith(port, [], 'unknown-receipt');
		expect(port.assignCategory).toHaveBeenCalledWith('unknown-receipt', 'cat-groceries', 'manual');
		expect(port.getVendorRule).not.toHaveBeenCalled();
	});
});

describe('assignCategoryFromRow — multi-row selection', () => {
	it('fans out to the whole selection when the clicked row is part of it', async () => {
		const port = makePort();
		const result = await callWith(port, ['r1', 'r2']);
		expect(port.bulkAssignCategory).toHaveBeenCalledWith(
			['r1', 'r2'],
			'cat-groceries',
			'manual'
		);
		expect(port.assignCategory).not.toHaveBeenCalled();
		expect(result).toEqual({ kind: 'bulk', count: 2, categoryName: 'Groceries' });
	});

	it('does NOT create a vendor rule for a fan-out — the selection spans merchants', async () => {
		const port = makePort();
		await callWith(port, ['r1', 'r3']);
		expect(port.getVendorRule).not.toHaveBeenCalled();
		expect(port.createVendorRule).not.toHaveBeenCalled();
	});

	it('takes the single-row path when only the clicked row is selected, so its rule is still created', async () => {
		const port = makePort();
		const result = await callWith(port, ['r1']);
		expect(port.assignCategory).toHaveBeenCalledOnce();
		expect(port.bulkAssignCategory).not.toHaveBeenCalled();
		expect(port.createVendorRule).toHaveBeenCalledOnce();
		expect(result.kind).toBe('single');
	});

	it('takes the single-row path when the clicked row is outside the selection', async () => {
		const port = makePort();
		const result = await callWith(port, ['r2', 'r3'], 'r1');
		expect(port.assignCategory).toHaveBeenCalledWith('r1', 'cat-groceries', 'manual');
		expect(port.bulkAssignCategory).not.toHaveBeenCalled();
		expect(result.kind).toBe('single');
	});
});

