import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render } from 'vitest-browser-svelte';
import { makeReceiptRow } from './builders/rowBuilders';
import {
	pageStore,
	supabaseMock,
	ReceiptServiceStub,
	setReceipts,
	setSession,
	fakeSession,
	resetHarness
} from './harness/appMocks';

// Same module boundaries as the other receipts-page render specs. See appMocks.ts.
vi.mock('$app/stores', () => ({ page: pageStore }));
vi.mock('$lib/supabaseClient', () => ({ supabase: supabaseMock }));
vi.mock('$app/navigation', () => ({ goto: () => {} }));
vi.mock('$app/paths', () => ({ resolve: (p: string) => p }));
vi.mock('$lib/utils/signedUrl', () => ({
	getSignedReceiptUrls: async () => ({}),
	getSignedReceiptUrl: async () => null
}));
vi.mock('$lib/utils/familyUtils', () => ({ getDefaultFamilyId: async () => null }));
vi.mock('$lib/services/ReceiptService', () => ({ ReceiptService: ReceiptServiceStub }));

import ReceiptsPage from '../../routes/receipts/+page.svelte';

/**
 * Behavior tests for the receipts page client-side filters.
 *
 * Replaces receipts-page.spec.ts, which mostly (a) reimplemented the filter/dedup
 * logic inline and asserted its own reimplementation, (b) contained tautologies
 * (`const uiImplemented = true; expect(uiImplemented).toBe(true)`), and (c) regex'd
 * the page source. The real logic those touched is already covered directly:
 *   - duplicate detection → duplicateDetection.spec.ts (19) + duplicateHelpers.spec.ts (8)
 *   - batch-upload isolation → batchUpload.spec.ts (7)
 *   - category assignment → ExpenseService.assignCategory tests
 * What was NOT covered — and what these assert — is that the page WIRES those filters
 * to the rendered table: toggling a filter actually hides/shows the right rows and the
 * count badge reflects the data. Built on the route-render harness (harness/appMocks.ts).
 */
describe('receipts page — client-side filters', () => {
	beforeEach(resetHarness);

	it('"needs date review" filter shows only suspicious-date receipts', async () => {
		setSession(fakeSession());
		// Distinct amount+date so the two rows are NOT a duplicate group — keeps the
		// needs-review badge the only status element on screen.
		setReceipts([
			makeReceiptRow({
				id: 's1',
				merchant_name: 'Suspicious Store',
				suspicious_date: true,
				total_amount: 100,
				transaction_date: '2025-08-01'
			}),
			makeReceiptRow({
				id: 'n1',
				merchant_name: 'Normal Store',
				suspicious_date: false,
				total_amount: 50,
				transaction_date: '2025-12-05'
			})
		]);

		const screen = render(ReceiptsPage);

		// Both rows present before filtering.
		await expect.element(screen.getByText('Suspicious Store')).toBeVisible();
		await expect.element(screen.getByText('Normal Store')).toBeVisible();

		// The count badge (role=status) reflects the one suspicious receipt.
		await expect.element(screen.getByRole('status')).toHaveTextContent('1');

		await screen.getByRole('checkbox', { name: 'Show only receipts needing date review' }).click();

		await expect.element(screen.getByText('Suspicious Store')).toBeVisible();
		await expect.element(screen.getByText('Normal Store')).not.toBeInTheDocument();
	});

	it('"potential duplicates" filter shows only duplicate-group receipts and counts them', async () => {
		setSession(fakeSession());
		// Two receipts sharing amount+date form a duplicate group; the third is unique.
		setReceipts([
			makeReceiptRow({
				id: 'd1',
				merchant_name: 'Dup Alpha',
				total_amount: 50,
				transaction_date: '2025-01-15'
			}),
			makeReceiptRow({
				id: 'd2',
				merchant_name: 'Dup Beta',
				total_amount: 50,
				transaction_date: '2025-01-15'
			}),
			makeReceiptRow({
				id: 'u1',
				merchant_name: 'Solo Store',
				total_amount: 99,
				transaction_date: '2025-03-01'
			})
		]);

		const screen = render(ReceiptsPage);

		await expect.element(screen.getByText('Solo Store')).toBeVisible();
		// Badge counts the two duplicate-group receipts.
		await expect.element(screen.getByRole('status')).toHaveTextContent('2');

		await screen.getByRole('checkbox', { name: 'Show only potential duplicate receipts' }).click();

