/**
 * The canonical description of "same merchant", as input/output pairs.
 *
 * Vendor normalization exists twice: `ExpenseService.normalizeVendor` in
 * TypeScript, and `public.normalize_vendor(text)` in SQL, which the AFTER INSERT
 * trigger on `receipts` uses. They must agree exactly — `vendor_category_rules`
 * stores an already-normalized `vendor_pattern`, so a divergence produces no
 * error at all. Rules simply stop matching, and the symptom surfaces weeks later
 * as "auto-categorization quietly stopped working".
 *
 * Both implementations are asserted against THIS list — the TypeScript one in
 * `ExpenseService.vendorRules.spec.ts` (inside the build gate), the SQL one in
 * `vendor-rule-trigger.spec.ts` (integration, run on demand). Editing one
 * implementation without the other should redden a test here.
 */
export interface VendorNormalizationCase {
	input: string;
	expected: string;
	why: string;
}

export const VENDOR_NORMALIZATION_CASES: VendorNormalizationCase[] = [
	{ input: 'SAFEWAY', expected: 'safeway', why: 'lowercased' },
	{ input: 'Safeway #1234!', expected: 'safeway 1234', why: 'punctuation stripped, digits kept' },
	{ input: '  Safeway  ', expected: 'safeway', why: 'surrounding whitespace trimmed' },
	{
		input: 'Safeway    Store    #123',
		expected: 'safeway store 123',
		why: 'runs of whitespace collapse to one'
	},
	{
		input: 'Tim Hortons\t\nOttawa',
		expected: 'tim hortons ottawa',
		why: 'tabs and newlines count as whitespace, not just spaces'
	},
	{
		input: 'CAFÉ RENÉ',
		expected: 'caf ren',
		why: 'accented letters are stripped, not folded — pinning current behaviour, not endorsing it'
	},
	{
		input: ' ~ Safeway',
		expected: ' safeway',
		why: 'trim runs BEFORE punctuation is stripped, so removing a leading "~" can expose a space that never gets trimmed. Pins the exact order of operations — an implementation that trims last would return "safeway" and silently stop matching.'
	}
];

