/**
 * Vendor-rule auto-categorization — Trigger Integration Suite
 *
 * Replaces `ReceiptService.autoCategory.spec.ts`. That suite mocked Supabase and
 * asserted a client-side helper (`autoAssignCategoryBestEffort`) that only ever
 * ran on the browser-upload path. The behaviour now lives in the
 * `apply_vendor_rule_after_insert` trigger, so it applies to every way a Receipt
 * can be created — and it can only be verified against a real Postgres.
 *
 * It also pins SQL `normalize_vendor()` to the SAME case list the TypeScript
 * `ExpenseService.normalizeVendor` is pinned to. `vendor_pattern` is stored
 * already-normalized, so a divergence between the two raises no error anywhere —
 * rules just quietly stop matching. This is the only executable check of that.
 *
 * ── Running it ──────────────────────────────────────────────────────────────
 * Like family-category-visibility.spec.ts, this hits a live Supabase with the
 * service-role key and is SKIPPED unless both env vars are set, so it never runs
 * in the default `npm run test:unit` / the Vercel build gate (which has no
 * Postgres). To run it:
 *
 *     supabase start
 *     npm run test:integration
 *
 * It creates and tears down its own family/user/category per `beforeEach`.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { createClient } from '@supabase/supabase-js';
import type { TestDatabase } from './builders/testDatabase';
import { VENDOR_NORMALIZATION_CASES } from '$lib/utils/vendorNormalizationCases';

const SUPABASE_URL = process.env.PUBLIC_SUPABASE_URL || '';
const SUPABASE_SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY || '';

const describeIf = (condition: boolean) => (condition ? describe : describe.skip);

describeIf(Boolean(SUPABASE_URL && SUPABASE_SERVICE_KEY))(
	'Vendor rule auto-categorization (database trigger)',
	() => {
		let supabase: ReturnType<typeof createClient<TestDatabase>>;

		let familyId: string;
		let userId: string;
		let userEmail: string;
		let groceriesId: string;
		let diningId: string;
		const createdReceiptIds: string[] = [];

		/** Insert a receipt the way every non-upload path does: a plain INSERT. */
		async function insertReceipt(merchantName: string | null) {
			const { data, error } = await supabase
				.from('receipts')
				.insert({
					user_id: userId,
					family_id: familyId,
					merchant_name: merchantName,
					total_amount: 42.5,
					transaction_date: '2026-08-01'
				})
				.select('id')
				.single();
			if (error) throw error;
			createdReceiptIds.push(data!.id);
			return data!.id as string;
		}

		async function categoryOf(receiptId: string) {
			const { data } = await supabase
				.from('expense_categories')
				.select('category_id, categorization_source')
				.eq('receipt_id', receiptId)
				.maybeSingle();
			return data;
		}

		beforeEach(async () => {
			supabase = createClient<TestDatabase>(SUPABASE_URL, SUPABASE_SERVICE_KEY);

			const { data: family, error: familyError } = await supabase
				.from('families')
				.insert({ name: 'Test Family for Vendor Rule Trigger' })
				.select()
				.single();
			if (familyError) throw familyError;
			familyId = family!.id;

			// Date.now() keeps the address unique across runs; it must be computed
			// once so createUser and any later sign-in agree.
			userEmail = `test-vendor-trigger-${Date.now()}@example.com`;
			const { data: user, error: userError } = await supabase.auth.admin.createUser({
				email: userEmail,
				password: 'testpassword123',
				email_confirm: true
			});
			if (userError) throw userError;
			userId = user.user.id;

			await supabase.from('family_members').insert({
				family_id: familyId,
				user_id: userId,
				status: 'active',
				role: 'owner',
				is_default: true
			});

			const { data: cats, error: catError } = await supabase
				.from('categories')
				.insert([
					{ family_id: familyId, name: 'Trigger Groceries', color: '#10B981' },
					{ family_id: familyId, name: 'Trigger Dining', color: '#EF4444' }
				])
				.select();
			if (catError) throw catError;
			groceriesId = cats!.find((c) => c.name === 'Trigger Groceries')!.id;
			diningId = cats!.find((c) => c.name === 'Trigger Dining')!.id;
		});

		afterEach(async () => {
			if (createdReceiptIds.length > 0) {
				await supabase.from('receipts').delete().in('id', createdReceiptIds);
				createdReceiptIds.length = 0;
			}
			if (familyId) {
				await supabase.from('vendor_category_rules').delete().eq('family_id', familyId);
				await supabase.from('categories').delete().eq('family_id', familyId);
				await supabase.from('family_members').delete().eq('family_id', familyId);
				await supabase.from('families').delete().eq('id', familyId);
			}
			if (userId) {
				await supabase.auth.admin.deleteUser(userId);
			}
		});

		describe('normalize_vendor() parity with ExpenseService.normalizeVendor', () => {
			it.each(VENDOR_NORMALIZATION_CASES)(
				'normalizes $input to $expected — $why',
				async ({ input, expected }) => {
					const { data, error } = await supabase.rpc('normalize_vendor', {
						merchant_name: input
					});
					expect(error).toBeNull();
					expect(data).toBe(expected);
				}
			);
		});

		describe('assignment on insert', () => {
			it('categorizes a new receipt from a matching vendor rule', async () => {
				await supabase.from('vendor_category_rules').insert({
					family_id: familyId,
					vendor_pattern: 'safeway',
					category_id: groceriesId
				});

				const receiptId = await insertReceipt('Safeway');

				expect(await categoryOf(receiptId)).toEqual({
					category_id: groceriesId,
					categorization_source: 'auto'
				});
			});

			it('matches on the normalized merchant, not the raw one', async () => {
				await supabase.from('vendor_category_rules').insert({
					family_id: familyId,
					vendor_pattern: 'safeway 1234',
					category_id: groceriesId
				});

				const receiptId = await insertReceipt('  SAFEWAY   #1234!  ');

				expect(await categoryOf(receiptId)).toMatchObject({ category_id: groceriesId });
			});

			it('leaves a receipt uncategorized when no rule matches', async () => {
				const receiptId = await insertReceipt('Unknown Merchant');
				expect(await categoryOf(receiptId)).toBeNull();
			});

			it('creates the receipt even when merchant_name is null', async () => {
				const receiptId = await insertReceipt(null);
				expect(receiptId).toBeTruthy();
				expect(await categoryOf(receiptId)).toBeNull();
			});

			it('does not apply another family’s rule', async () => {
				const { data: otherFamily } = await supabase
					.from('families')
					.insert({ name: 'Other Family' })
					.select()
					.single();
				const { data: otherCategory } = await supabase
					.from('categories')
					.insert({ family_id: otherFamily!.id, name: 'Other Groceries' })
					.select()
					.single();
				await supabase.from('vendor_category_rules').insert({
					family_id: otherFamily!.id,
					vendor_pattern: 'safeway',
					category_id: otherCategory!.id
				});

				const receiptId = await insertReceipt('Safeway');
				expect(await categoryOf(receiptId)).toBeNull();

				await supabase.from('vendor_category_rules').delete().eq('family_id', otherFamily!.id);
				await supabase.from('categories').delete().eq('family_id', otherFamily!.id);
				await supabase.from('families').delete().eq('id', otherFamily!.id);
			});

			it('applies to every subsequent receipt from the same vendor', async () => {
				await supabase.from('vendor_category_rules').insert({
					family_id: familyId,
					vendor_pattern: 'safeway',
					category_id: groceriesId
				});

				const first = await insertReceipt('Safeway');
				const second = await insertReceipt('SAFEWAY');

				expect(await categoryOf(first)).toMatchObject({ category_id: groceriesId });
				expect(await categoryOf(second)).toMatchObject({ category_id: groceriesId });
			});
		});

		describe('never overwrites an existing categorization', () => {
			it('leaves a manual category alone when the importer writes one after insert', async () => {
				// The historical importer's shape: insert receipts, then upsert the
				// file's own categories. The trigger's 'auto' row must lose.
				await supabase.from('vendor_category_rules').insert({
					family_id: familyId,
					vendor_pattern: 'safeway',
					category_id: groceriesId
				});

				const receiptId = await insertReceipt('Safeway');
				expect(await categoryOf(receiptId)).toMatchObject({ category_id: groceriesId });

				await supabase
					.from('expense_categories')
					.upsert(
						{ receipt_id: receiptId, category_id: diningId, categorization_source: 'manual' },
						{ onConflict: 'receipt_id' }
					);

				expect(await categoryOf(receiptId)).toEqual({
					category_id: diningId,
					categorization_source: 'manual'
				});
			});
		});
	}
);

