/**
 * #{#vca5a} The retroactive net for vendor rules.
 *
 * The `apply_vendor_rule_after_insert` trigger categorizes receipts as they are
 * created, so this is not what makes new receipts work. What it catches is the
 * other direction: a rule created *after* a receipt exists only fans out over
 * the rows that happened to be on screen at the time, so receipts outside that
 * filter — or on another family member's screen — stay uncategorized. Without
 * this the Category column would show stale "Uncategorized" rows that fix
 * themselves the moment you visit Expenses.
 */
async function checkForAutoCategorizationMatches() {
	if (!familyId) return;

	try {
		const expenseService = new ExpenseService(supabase);
		// Unfiltered on purpose — the point is to reach rows the filtered fan-out
		// could not.
		const candidates: VendorRuleCandidate[] = allReceipts.map((r) => ({
			receipt_id: r.id,
			merchant_name: r.merchant_name ?? '',
			category_id: categoryMap[r.id]?.id ?? null
		}));

		const totalAssigned = await expenseService.applyAllVendorRules(familyId, candidates);

		if (totalAssigned > 0) {
			await loadCategories();
			flashSuccess(
				`Auto-categorized ${totalAssigned} receipt${totalAssigned === 1 ? '' : 's'} based on vendor rules`
			);
		}
	} catch (err) {
		// Background operation — never surfaced to the user.
		console.error('Error checking auto-categorization:', err);
	}
}

