1	/**
2	 * Shared category-assignment behaviour, exercised through the port rather than a
3	 * page. Both list pages call `assignCategoryFromRow`, so these cases are the
4	 * single description of what picking a category in a row does.
5	 */
6	
7	import { describe, it, expect, vi } from 'vitest';
8	import { assignCategoryFromRow, type CategoryAssignmentPort } from './categoryAssignment';
9	import type { VendorRuleCandidate } from '$lib/services/ExpenseService';
10	import type { Category } from '$lib/types/Category';
11	
12	const GROCERIES: Category = {
13		id: 'cat-groceries',
14		family_id: 'fam-1',
15		name: 'Groceries',
16		color: '#00ff00'
17	} as Category;
18	
19	function makePort(overrides: Partial<CategoryAssignmentPort> = {}): CategoryAssignmentPort {
20		return {
21			assignCategory: vi.fn().mockResolvedValue(undefined),
22			bulkAssignCategory: vi.fn().mockResolvedValue(undefined),
23			getVendorRule: vi.fn().mockResolvedValue(null),
24			createVendorRule: vi.fn().mockResolvedValue(undefined),
25			normalizeVendor: (name: string) => name.toLowerCase().trim(),
26			applyRuleToVisibleExpenses: vi.fn().mockResolvedValue(0),
27			...overrides
28		};
29	}
30	
31	const rows: VendorRuleCandidate[] = [
32		{ receipt_id: 'r1', merchant_name: 'Safeway', category_id: null },
33		{ receipt_id: 'r2', merchant_name: 'Safeway', category_id: null },
34		{ receipt_id: 'r3', merchant_name: 'Dentist', category_id: 'cat-health' }
35	];
36	
37	function callWith(port: CategoryAssignmentPort, selection: string[] = [], receiptId = 'r1') {
38		return assignCategoryFromRow(port, {
39			receiptId,
40			category: GROCERIES,
41			familyId: 'fam-1',
42			selection: new Set(selection),
43			visibleRows: rows
44		});
45	}
46	
47	describe('assignCategoryFromRow — single row', () => {
48		it('assigns the category to just that receipt, manually', async () => {
49			const port = makePort();
50			await callWith(port);
51			expect(port.assignCategory).toHaveBeenCalledWith('r1', 'cat-groceries', 'manual');
52			expect(port.bulkAssignCategory).not.toHaveBeenCalled();
53		});
54	
55		it('creates a vendor rule when the merchant has none', async () => {
56			const port = makePort();
57			const result = await callWith(port);
58			expect(port.createVendorRule).toHaveBeenCalledWith('fam-1', 'Safeway', 'cat-groceries');
59			expect(result).toMatchObject({ kind: 'single', ruleCreated: true });
60		});
61	
62		it('leaves an existing vendor rule alone', async () => {
63			const port = makePort({
64				getVendorRule: vi.fn().mockResolvedValue({ category_id: 'cat-other', category_name: 'Other' })
65			});
66			const result = await callWith(port);
67			expect(port.createVendorRule).not.toHaveBeenCalled();
68			expect(port.applyRuleToVisibleExpenses).not.toHaveBeenCalled();
69			expect(result).toMatchObject({ kind: 'single', ruleCreated: false, autoAppliedCount: 0 });
70		});
71	
72		it('applies a newly created rule to the other visible rows and reports the count', async () => {
73			const port = makePort({ applyRuleToVisibleExpenses: vi.fn().mockResolvedValue(2) });
74			const result = await callWith(port);
75			expect(port.applyRuleToVisibleExpenses).toHaveBeenCalledWith(rows, 'safeway', 'cat-groceries');
76			expect(result).toMatchObject({ kind: 'single', autoAppliedCount: 2 });
77		});
78	
79		it('skips vendor-rule work when there is no family', async () => {
80			const port = makePort();
81			const result = await assignCategoryFromRow(port, {
82				receiptId: 'r1',
83				category: GROCERIES,
84				familyId: null,
85				selection: new Set(),
86				visibleRows: rows
87			});
88			expect(port.assignCategory).toHaveBeenCalledOnce();
89			expect(port.getVendorRule).not.toHaveBeenCalled();
90			expect(result).toMatchObject({ ruleCreated: false });
91		});
92	
93		it('skips vendor-rule work for a row it cannot find a merchant for', async () => {
94			const port = makePort();
95			await callWith(port, [], 'unknown-receipt');
96			expect(port.assignCategory).toHaveBeenCalledWith('unknown-receipt', 'cat-groceries', 'manual');
97			expect(port.getVendorRule).not.toHaveBeenCalled();
98		});
99	});
100	
101	describe('assignCategoryFromRow — multi-row selection', () => {
102		it('fans out to the whole selection when the clicked row is part of it', async () => {
103			const port = makePort();
104			const result = await callWith(port, ['r1', 'r2']);
105			expect(port.bulkAssignCategory).toHaveBeenCalledWith(['r1', 'r2'], 'cat-groceries', 'manual');
106			expect(port.assignCategory).not.toHaveBeenCalled();
107			expect(result).toEqual({ kind: 'bulk', count: 2, categoryName: 'Groceries' });
108		});
109	
110		it('does NOT create a vendor rule for a fan-out — the selection spans merchants', async () => {
111			const port = makePort();
112			await callWith(port, ['r1', 'r3']);
113			expect(port.getVendorRule).not.toHaveBeenCalled();
114			expect(port.createVendorRule).not.toHaveBeenCalled();
115		});
116	
117		it('takes the single-row path when only the clicked row is selected, so its rule is still created', async () => {
118			const port = makePort();
119			const result = await callWith(port, ['r1']);
120			expect(port.assignCategory).toHaveBeenCalledOnce();
121			expect(port.bulkAssignCategory).not.toHaveBeenCalled();
122			expect(port.createVendorRule).toHaveBeenCalledOnce();
123			expect(result.kind).toBe('single');
124		});
125	
126		it('takes the single-row path when the clicked row is outside the selection', async () => {
127			const port = makePort();
128			const result = await callWith(port, ['r2', 'r3'], 'r1');
129			expect(port.assignCategory).toHaveBeenCalledWith('r1', 'cat-groceries', 'manual');
130			expect(port.bulkAssignCategory).not.toHaveBeenCalled();
131			expect(result.kind).toBe('single');
132		});
133	});

